WFJ.Data.add("gossip", {
  ["6400ab348c3885f9"] = { "Theresa, porta questo a padre Niflheim.", "." },
  ["640a42d6d5ca0779"] = { "Sì, esatto. E a te che importa?", "." },
  ["641d05c243615d17"] = { "Purtroppo Zephras è in declino. Gli spiriti elementali del vento che ci portarono qui a Skywall tante migliaia di anni fa sono svaniti, e abbiamo perso gran parte della magia da cui dipendevamo da millenni.\n\nAnche l'isola stessa è pericolosamente instabile, e abbiamo perfino perso i contatti con le altre province insulari degli shen'dorei. I pochi Windshaper che ancora possiedono il dono della vista celeste hanno cercato di contattare i nostri fratelli e sorelle sulle altre isole, ma non abbiamo avuto risposta.\n\nMolti di noi temono che gli shen'dorei qui su Zephras siano tutto ciò che resta del nostro popolo.", "." },
  ["642b65efe59b4a50"] = { "Ho sentito che là sotto ci sono ancora degli orchi sepolti.", "." },
  ["642d7ab408ecf7ab"] = { "Ehi, <amico/signora>, pensi di potermi dare una mano con una cosa? Sono proprio nei guai...", "." },
  ["642d7d1d51c9b964"] = { "Proprio come pensavo, le gemme e la collana non contano. Conta solo la fonte di energia.", "." },
  ["64300cbb01bd848c"] = { "La West Frostwolf Tower è stata presa dall'⟦Horde=Orda⟧!", "." },
  ["6435ce777126fc37"] = { "Va bene, va bene! Tocca a te!", "." },
  ["644efb935249cbff"] = { "C'è mancato poco, {name}! Be', muoviamoci, c'è ancora un bel pezzo di strada fino a ⟦Ratchet=Porto Paranco⟧!", "." },
  ["64590542939419e1"] = { "Molte volte le mie lame hanno abbattuto il bersaglio prima ancora che si avvicinasse. Il segreto sta nel colpo di polso.", "." },
  ["64622ca9562238f0"] = { "Ho perso il mio ⟦Drape of Vaulted Secrets=Drappo dei Segreti Ignoti⟧. Puoi sostituirmelo?", "." },
  ["6462db059ab80edb"] = { "A ⟦Nighthaven=Nottequieta⟧! Tieni vicino il tuo esercito, campione.", "." },
  ["6468bef4e8768130"] = { "Tesoro, il cibo è pronto. Vieni a lavarti e mangia.", "." },
  ["646e6e58c304a061"] = { "%s inizia a rispondere a ogni attacco contro di lui!", "." },
  ["6478e7d9fbe4ce57"] = { "Sì, signor sindaco.", "." },
  ["647d266bcaed08e9"] = { "%s viene divorato!", "." },
  ["647f5818e0183cc3"] = { "È proprio Reethe. Andiamo a sentire cos'ha da dire, eh?", "." },
  ["6483dc2f27b87439"] = { "Pesce tanto buono. Tu viene imparare pesce? Mangia pesce? Mmmmm...", "." },
  ["648554f1b64a5b0e"] = { "Ho la tua bambola! Marameo!", "." },
  ["648b9487e6f5f3e5"] = { "%s batte le mani con entusiasmo.", "." },
  ["648c113eee9bfd16"] = { "Vediamo, vediamo. Avevo quei numeri qui da qualche parte. Ah sì, eccoli! Finora l'⟦Alliance=Alleanza⟧ ha raccolto $2047w stranglekelp sui $2048w necessari. Qui dice anche che abbiamo $2053w Fiori di Loto Purpureo su $2055w e $2057w Lacrime di Arthas sulle $2058w necessarie.", "." },
  ["649078b2dce9d490"] = { "La tua armatura è pronta, {name}.", "." },
  ["6493c1897cfe6a2b"] = { "Impara qual è il tuo posto, mortale!", "." },
  ["6495ca1b2ae31447"] = { "⟦Glacial Vest=Veste Glaciale⟧.", "." },
  ["64a04bf0dab24e2d"] = { "Il capitano dell'⟦Horde=Orda⟧ Galvangar è caduto. Sconfiggete ⟦Drek'Thar=Drek'thar⟧ e la vittoria sarà nostra!", "." },
  ["64a37d6313e15d51"] = { "%s si accomoda per leggere il ⟦Yagyin's Digest=Compendio di Yagyin⟧...", "." },
  ["64a7024245087508"] = { "Che cos'è questo?! Come osi!", "." },
  ["64ab4e309756a044"] = { "La ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧ si trova nell'angolo meridionale della ⟦Alterac Valley=Valle d'Alterac⟧ e protegge il ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧, patria dell'omonimo clan di orchi. Tutti i territori dell'⟦Horde=Orda⟧ nella ⟦Alterac Valley=Valle d'Alterac⟧ dipendono da questo unico centro di potere.\n\nLa ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧ è intatta.", "." },
  ["64ab578a7ee66eec"] = { "Un po' di tortura, un pizzico di magia e un'abbondante dose di chirurgia invasiva. Era cosciente, naturalmente.", "." },
  ["64b5f3fe1a919ca5"] = { "Basta! Tornate ai vostri angoli! Bel combattimento, tutti e due.", "." },
  ["64bfca1b5a2b96bf"] = { "Gli elementali dell'acqua sono in guerra con gli elementali del fuoco, il che in un certo senso significa che sono in guerra con noi. Uno dei loro capi, Idraxis, sta radunando agenti per la sua causa...", "." },
  ["64c0422be6fcf7ff"] = { "Muori, {name}, nullità!", "." },
  ["64c47477b636e4a1"] = { "Perché le guardie di ⟦Stormwind=Roccavento⟧ non sono arrivate?", "." },
  ["64c61187823e8f71"] = { "Si è passato il limite. Come osa il Flagello attaccare ⟦Undercity=Sepulcra⟧! Distruggetelo prima che ne arrivino altri!", "." },
  ["64c961c6752f9992"] = { "C'è molto lavoro da fare prima che la ⟦Charred Vale=Valle Bruciata⟧ possa tornare la foresta rigogliosa di un tempo.\n\nLibera la zona da quelle turpi minacce, {name}! Solo allora potremo cominciare a reclamare ciò che appartiene alla natura.", "." },
  ["64ca7febb8b4da53"] = { "Di tutti i luoghi meravigliosi di Darnassus, verso quale vuoi che ti indirizzi?", "." },
  ["64cdd9b121561453"] = { "Abbiamo molte provviste per la ricostruzione. Ancora un po' e ne avremo abbastanza per riparare Dun Baldar e tornare in battaglia!", "." },
  ["64d480a1c5171d95"] = { "La ⟦Crystal Restore=Guarigione del Cristallo⟧ è un oggetto difficile da procurarsi.\n\nCredo che provenga dal ⟦Un'Goro Crater=Cratere di Un'Goro⟧, quindi ti conviene andare là.", "." },
  ["64da511427692bef"] = { "Troverai Tannysa davanti ad Alchemy Needs, nel ⟦Mage Quarter=Quartiere dei Maghi⟧.", "." },
  ["64dc6df37687d4d9"] = { "Onorate i vostri eroi! Oggi hanno inferto un duro colpo a uno dei nostri nemici più odiati! Il falso Capoguerra, Rend Manonera, è caduto!", "." },
  ["64efbf0b65e41edb"] = { "Quindi vuoi fare il fabbro, eh? Prendi un grembiule e un martello, <ragazzo/ragazza>, vediamo cosa sai fare.", "." },
  ["64f1973059597602"] = { "Stolto mortale, quando mi libereranno ti squarcerò l'anima in due!", "." },
  ["64f64bebe573a50b"] = { "Il cucchiaio non esiste.", "." },
  ["64fe2c079e0b67b2"] = { "È Dwukk. Lo trovi accanto alla forgia ardente, nell'angolo nord-ovest della città.", "." },
